class Solution {
public:
 vector<int> getSumAbsoluteDifferences(vector<int>& nums) {
  long long total=accumulate(nums.begin(),nums.end(),0LL),left=0;
  int n=nums.size(); vector<int> ans(n);
  for(int i=0;i<n;++i){
   total-=nums[i];
   ans[i]=(long long)i*nums[i]-left+total-(long long)(n-i-1)*nums[i];
   left+=nums[i];
  }
  return ans;
 }
};
